28	function readCmdlineByPid(pid) {
29	    if (!pid || process.platform !== 'linux') return '';
30	    try {
31	        const raw = fs.readFileSync(`/proc/${pid}/cmdline`, 'utf8');
32	        return raw.replace(/\u0000/g, ' ').trim();
33	    } catch (e) {
34	        return '';
35	    }
36	}
37	
38	function getParentPid(pid) {
39	    if (!pid || process.platform !== 'linux') return 0;
40	    try {
41	        const stat = fs.readFileSync(`/proc/${pid}/stat`, 'utf8');
42	        const parts = stat.split(' ');
43	        return parseInt(parts[3], 10) || 0;
44	    } catch (e) {
45	        return 0;
46	    }
47	}
