49	function assertNotRunningWithXvfb() {
50	    if (process.platform !== 'linux') return;
51	
52	    const parentCmd = readCmdlineByPid(process.ppid);
53	    const grandParentPid = getParentPid(process.ppid);
54	    const grandParentCmd = readCmdlineByPid(grandParentPid);
55	    const xauthority = String(process.env.XAUTHORITY || '').toLowerCase();
56	    const display = String(process.env.DISPLAY || '').toLowerCase();
57	
58	    const hit =
59	        /\bxvfb-run\b/.test(parentCmd) ||
60	        /\bxvfb-run\b/.test(grandParentCmd) ||
61	        xauthority.includes('xvfb-run') ||
62	        display.includes('xvfb');
63	
64	    if (hit) {
65	        throw new Error('禁止使用 xvfb 运行项目。请在远程桌面图形会话中直接执行: node index.js');
66	    }
67	}
