88	async function pollEmailCode(mailProvider, maxAttempts = 30, interval = 5000) {
89	    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
90	        console.log(`[Mail] 轮询邮箱验证码... (${attempt}/${maxAttempts})`);
91	
92	        try {
93	            const mails = await mailProvider.getMails(5, 0);
94	            if (mails.length > 0) {
95	                const latest = mails[0];
96	                const raw = latest.raw || '';
97	
98	                // 从 MIME 原始邮件中提取正文（跳过邮件头）
99	                // 正文在 Content-Transfer-Encoding 之后的空行后面
100	                // 或者在 HTML 内容中查找验证码
101	                let body = raw;
102	
103	                // 尝试提取 HTML/text 正文（在最后一个 boundary 后）
104	                const htmlMatch = raw.match(/Content-Type:\s*text\/html[\s\S]*?\r?\n\r?\n([\s\S]*?)(?:--[^\r\n]+--|$)/i);
105	                if (htmlMatch) {
106	                    body = htmlMatch[1];
107	                } else {
108	                    // 没有 HTML，取最后一段（通常是正文）
109	                    const parts = raw.split(/\r?\n\r?\n/);
110	                    if (parts.length > 1) {
111	                        body = parts.slice(Math.max(1, parts.length - 3)).join('\n');
112	                    }
113	                }
114	
115	                // 方法1：找 "code" / "验证码" / "verification" 附近的6位数字
116	                const codePatterns = [
117	                    /(?:code|验证码|verification|verify)[^\d]{0,30}(\d{6})/i,
118	                    /(\d{6})[^\d]{0,30}(?:code|验证码|verification)/i,
119	                    />\s*(\d{6})\s*</,  // HTML 标签之间的6位数字
120	                ];
121	                for (const pattern of codePatterns) {
122	                    const match = body.match(pattern);
123	                    if (match) {
124	                        console.log(`[Mail] 收到验证码: ${match[1]} (pattern: ${pattern.source.substring(0, 30)})`);
125	                        return match[1];
126	                    }
127	                }
128	
129	                // 方法2：兜底 - 在正文中找任何6位数字（排除明显的非验证码）
130	                const allSixDigits = body.match(/\b(\d{6})\b/g) || [];
131	                const filtered = allSixDigits.filter(d => !raw.includes(`t=${d}`) && !raw.includes(`x=${d}`));
132	                if (filtered.length > 0) {
133	                    console.log(`[Mail] 收到验证码 (兜底): ${filtered[0]}`);
134	                    return filtered[0];
135	                }
136	
137	                console.log(`[Mail] 邮件已收到但未提取到验证码，正文前200字: ${body.substring(0, 200)}`);
138	            }
139	        } catch (error) {
140	            console.error(`[Mail] 查询出错: ${error.message}`);
141	        }
142	
143	        await new Promise(r => setTimeout(r, interval));
144	    }
145	
146	    throw new Error(`邮箱验证码超时（等待 ${(maxAttempts * interval) / 1000} 秒）`);
147	}
