161	        if (parts.length > 1) {
162	            body = parts.slice(Math.max(1, parts.length - 3)).join('\n');
163	        }
164	    }
165	
166	    const codePatterns = [
167	        /(?:code|éªŒè¯ç |verification|verify)[^\d]{0,30}(\d{6})/i,
168	        /(\d{6})[^\d]{0,30}(?:code|éªŒè¯ç |verification)/i,
169	        />\s*(\d{6})\s*</,
170	    ];
171	    for (const pattern of codePatterns) {
172	        const match = body.match(pattern);
173	        if (match) return match[1];
174	    }
175	
176	    const allSixDigits = body.match(/\b(\d{6})\b/g) || [];
