201	function readJsonArray(filePath) {
202	    if (!fs.existsSync(filePath)) return [];
203	    try {
204	        const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
205	        if (Array.isArray(parsed)) return parsed;
206	        if (parsed && typeof parsed === 'object') return [parsed];
207	        return [];
208	    } catch (e) {
209	        return [];
210	    }
211	}
