10	function parseProxyEndpoint(endpoint) {
11	    if (!endpoint || typeof endpoint !== 'string') return null;
12	    const raw = endpoint.trim();
13	    if (!raw) return null;
14	
15	    try {
16	        const withScheme = raw.includes('://') ? raw : `http://${raw}`;
17	        const u = new URL(withScheme);
18	
19	        if (!['http:', 'https:'].includes(u.protocol)) {
20	            return null;
21	        }
22	
23	        const port = parseInt(u.port, 10) || (u.protocol === 'https:' ? 443 : 80);
24	        if (!u.hostname || !port) return null;
25	
26	        return {
27	            host: u.hostname,
28	            port,
29	            username: decodeURIComponent(u.username || ''),
30	            password: decodeURIComponent(u.password || ''),
31	        };
32	    } catch (e) {
33	        return null;
34	    }
35	}
