37	function detectProxyFromEnv() {
38	    const env = process.env;
39	    const raw = env.HTTPS_PROXY || env.https_proxy || env.HTTP_PROXY || env.http_proxy || env.ALL_PROXY || env.all_proxy;
40	    if (!raw) return null;
41	
42	    const parsed = parseProxyEndpoint(raw);
43	    if (!parsed) return null;
44	
45	    return { ...parsed, source: 'env' };
46	}
