48	function parseWinHttpProxyText(text) {
49	    if (!text) return null;
50	
51	    // 优先提取 https=...;http=... 形式
52	    const httpsMatch = text.match(/https\s*=\s*([^;\s\r\n]+)/i);
53	    const httpMatch = text.match(/http\s*=\s*([^;\s\r\n]+)/i);
54	    const endpoint = (httpsMatch && httpsMatch[1]) || (httpMatch && httpMatch[1]);
55	    if (endpoint) return endpoint;
56	
57	    // 兼容 "Proxy Server(s) : host:port" 形式
58	    const lineMatch = text.match(/Proxy\s*Server\(s\)\s*:\s*([^\r\n]+)/i);
59	    if (lineMatch && lineMatch[1]) {
60	        const value = lineMatch[1].trim();
61	        if (value && !/direct access|no proxy/i.test(value)) return value;
62	    }
63	
64	    // 兜底：抓第一个 host:port
65	    const hostPort = text.match(/([a-zA-Z0-9.-]+:\d{2,5})/);
66	    if (hostPort && hostPort[1]) return hostPort[1];
67	
68	    return null;
69	}
