81	        const endpoint = parseWinHttpProxyText(out);
82	        if (!endpoint) return null;
83	
84	        const parsed = parseProxyEndpoint(endpoint);
85	        if (!parsed) return null;
86	
87	        return { ...parsed, source: 'winhttp' };
88	    } catch (e) {
89	        return null;
90	    }
91	}
