218	                            host: this.proxy.host,
219	                            port: this.proxy.port,
220	                        };
221	                        if (this.proxy.username || this.proxy.password) {
222	                            requestConfig.proxy.auth = {
223	                                username: this.proxy.username || '',
224	                                password: this.proxy.password || '',
225	                            };
226	                        }
227	                    }
228	
229	                    response = await axios.post('https://auth.openai.com/oauth/token', body, {
230	                        ...requestConfig,
231	                    });
232	                    break;
233	                } catch (err) {
234	                    lastError = err;
235	
236	                    const status = err?.response?.status;
237	                    const code = err?.code;
238	                    const retryable =
239	                        code === 'EAI_AGAIN' ||
240	                        code === 'ENOTFOUND' ||
241	                        code === 'ECONNRESET' ||
242	                        code === 'ETIMEDOUT' ||
243	                        code === 'ECONNABORTED' ||
244	                        status === 429 ||
245	                        (status >= 500 && status <= 599);
246	
247	                    if (!retryable || attempt === maxAttempts) {
248	                        throw err;
249	                    }
250	
251	                    const waitMs = attempt * 3000;
252	                    console.warn(`[OAuth] 换 Token 第 ${attempt} 次失败(${code || status || 'unknown'})，${waitMs}ms 后重试...`);
253	                    await SLEEP(waitMs);
254	                }
255	            }
256	
257	            if (!response) {
258	                throw lastError || new Error('换取 Token 失败: 未获得响应');
259	            }
260	
261	            const tokens = response.data;
262	
263	            // 解析 JWT 获取 account_id
264	            let accountId = "";
265	            try {
266	                const payloadStr = Buffer.from(tokens.access_token.split('.')[1], 'base64').toString('utf8');
267	                const payload = JSON.parse(payloadStr);
268	                const apiAuth = payload['https://api.openai.com/auth'] || {};
269	                accountId = apiAuth.chatgpt_account_id || "";
270	            } catch (e) {
271	                console.error('[OAuth] 解析 access_token 获取 account_id 失败:', e.message);
272	            }
273	
274	            const now = new Date();
275	            const expiredTime = new Date(now.getTime() + tokens.expires_in * 1000);
276	
277	            const outData = {
278	                access_token: tokens.access_token,
279	                account_id: accountId,
280	                disabled: false,
281	                email: email,
282	                expired: expiredTime.toISOString().replace(/\.[0-9]{3}Z$/, '+08:00'),
283	                id_token: tokens.id_token,
284	                last_refresh: now.toISOString().replace(/\.[0-9]{3}Z$/, '+08:00'),
285	                refresh_token: tokens.refresh_token,
286	                type: 'codex'
287	            };
288	
289	            // 保存到文件（支持双写/多目录）
290	            const outputDirs = config.tokenOutputDirs.length > 0
291	                ? [...new Set(config.tokenOutputDirs)]
292	                : [config.tokenOutputDir || path.join(process.cwd(), 'tokens')];
293	            const safeEmail = String(email || 'unknown')
294	                .trim()
295	                .replace(/[\\/:*?"<>|]/g, '_');
296	            const filename = `codex-${safeEmail}-free.json`;
297	            const savedPaths = [];
298	            for (const dir of outputDirs) {
299	                if (!fs.existsSync(dir)) {
300	                    fs.mkdirSync(dir, { recursive: true });
301	                }
302	                const filepath = path.join(dir, filename);
303	                fs.writeFileSync(filepath, JSON.stringify(outData, null, 2));
304	                savedPaths.push(filepath);
305	            }
306	
307	            console.log(`[OAuth] Token 成功保存至: ${savedPaths.join(' | ')}`);
308	            return outData;
309	        } catch (error) {
310	            const apiErrorCode = error?.response?.data?.error?.code;
311	            if (apiErrorCode === 'unsupported_country_region_territory') {
312	                console.error('[OAuth] 地区受限：当前出口 IP 不支持，请配置可用代理后重试');
313	            }
314	            console.error('[OAuth] 换取 Token 失败:', error.response ? error.response.data : error.message);
315	            throw error;
316	        }
317	    }
318	}
